  //});

  volume.CreateSection(new SectionDefinition()
  {
    Name = $"Circle {s + 1}",
    VoxelPosition = new Coordinate3D(volumeSize.X / 2, volumeSize.Y / 2, volumeSize.Z / 2),
    Normal = voxelLayer.GetNormal(orientation, 0.0),
    IsVisible = true
  });
}

